document.querySelectorAll("[data-sponsoren] [data-alle]").forEach(function(e){e.addEventListener("click",function(){const t=e.previousElementSibling;t.querySelectorAll("li[hidden]").forEach(function(e){e.hidden=!1}),e.remove(),t.querySelector("li").setAttribute("tabindex","-1"),t.querySelector("li").focus({preventScroll:!0})})}),document.querySelectorAll("[data-aussteller]").forEach(function(e){const t=e.querySelectorAll("[data-filter]"),r=e.querySelectorAll(".aussteller-karte");t.forEach(function(e){e.addEventListener("click",function(){const l=e.dataset.filter;t.forEach(function(t){t.setAttribute("aria-pressed",t===e?"true":"false")}),r.forEach(function(e){e.hidden=""!==l&&!(" "+e.dataset.kategorien+" ").includes(" "+l+" ")})})})});